/**
 * Pack the project into one text file, for handing to an LLM.
 *
 *   node tools/bundle.js [tier]
 *
 * Tiers, smallest first — pick the largest one that fits the context you have:
 *
 *   engine   the rules and the data, and nothing else. The engine is a pure
 *            state machine with no DOM in it, so this tier is self-contained
 *            and is the right one for a question about how the GAME works.
 *   source   everything that ships: engine, data, UI, netcode, styles. The
 *            right one for a question about the app.
 *   full     source plus the test suite, the simulator and the deploy config.
 *            Everything a new contributor would clone.
 *
 * Output goes to bundle/persona-<tier>.txt, which is gitignored.
 *
 * Files are listed in dependency order — data before engine before UI — so the
 * bundle reads forwards: nothing refers to something the reader has not met
 * yet. Binary assets and the lockfile are skipped; neither is worth the tokens.
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

/** Never worth the tokens: compiled assets, images, and the lockfile. */
const SKIP = /package-lock\.json$|\.(png|jpe?g|gif|ico|woff2?|ttf|svg)$/i;

/**
 * Reading order. Earlier patterns win, so a file matched by several appears
 * once, at its first match. Anything unmatched is appended at the end rather
 * than dropped — a bundle that silently omits a new directory is worse than
 * one with a file in an odd place.
 */
const ORDER = [
  'README.md',
  'package.json',
  'vite.config.js',
  'index.html',
  'src/data/',
  'src/engine/',
  'src/ui/',
  'src/net/',
  'src/styles/',
  'src/main.js',
  'tools/',
  'server/',
  'tests/',
  'deploy/',
];

const TIERS = {
  engine: (f) => /^src\/(engine|data)\//.test(f) || f === 'README.md' || f === 'package.json',
  source: (f) => /^(src\/|index\.html|README\.md|package\.json|vite\.config\.js)/.test(f),
  full: () => true,
};

const tier = process.argv[2] ?? 'full';
if (!TIERS[tier]) {
  console.error(`Unknown tier "${tier}". Expected one of: ${Object.keys(TIERS).join(', ')}`);
  process.exit(1);
}

const tracked = execFileSync('git', ['ls-files'], { cwd: ROOT, encoding: 'utf8' })
  .split('\n')
  .filter(Boolean)
  .filter((f) => !SKIP.test(f))
  .filter(TIERS[tier]);

const rank = (f) => {
  const i = ORDER.findIndex((p) => (p.endsWith('/') ? f.startsWith(p) : f === p));
  return i === -1 ? ORDER.length : i;
};
const files = tracked.sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));

const out = [];
out.push('='.repeat(78));
out.push(`VELVET DUEL — ${tier.toUpperCase()} BUNDLE`);
out.push('='.repeat(78));
out.push('');
out.push('An unofficial, fan-made Persona-inspired card game. Single-page vanilla JS');
out.push('built with Vite. No framework, no backend for local play.');
out.push('');
out.push('ARCHITECTURE, in one paragraph: the engine is a pure deterministic state');
out.push('machine, completely separate from the UI. The whole of it is two functions —');
out.push('`applyAction(state, action)` returns a NEW state, and `getLegalActions(state,');
out.push('player)` lists what is legal right now. There is no DOM access and no');
out.push('Math.random() anywhere inside the engine: all randomness comes from a seeded');
out.push('RNG carried in the game state, which is why a match is reproducible from its');
out.push('seed and why the state is plain JSON that can be saved or sent over a wire.');
out.push('Every card lives in src/data/cards.json; the UI renders whatever');
out.push('getLegalActions offers and never decides a rule for itself.');
out.push('');
out.push(`Files: ${files.length}. Generated by tools/bundle.js — regenerate rather than edit.`);
out.push('');
out.push('-'.repeat(78));
out.push('CONTENTS');
out.push('-'.repeat(78));
for (const f of files) out.push(`  ${f}`);
out.push('');

for (const file of files) {
  const body = readFileSync(join(ROOT, file), 'utf8');
  out.push('');
  out.push('='.repeat(78));
  out.push(`FILE: ${file}`);
  out.push('='.repeat(78));
  out.push(body.replace(/\s+$/, ''));
}
out.push('');

const text = out.join('\n');
mkdirSync(join(ROOT, 'bundle'), { recursive: true });
const dest = join(ROOT, 'bundle', `persona-${tier}.txt`);
writeFileSync(dest, text);

const bytes = Buffer.byteLength(text);
console.log(`${dest}`);
console.log(`  ${files.length} files, ${(bytes / 1024).toFixed(0)} KB, ~${Math.round(bytes / 4000)}k tokens (rough)`);
